1	/* The web control surface: one column, large touch targets, the
2	   waiting mark in words as well as colour. Light and dark follow the
3	   phone. */
4	
5	:root {
6	  color-scheme: light dark;
7	  --bg: #ffffff;
8	  --fg: #1a1a1a;
