555	
556	/// The 101 that switches a connection to WebSocket. The request was
557	/// already read by `read_request`, so `tungstenite::accept` cannot be
558	/// used; the stream is wrapped with `from_raw_socket` after this.
559	fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
560	    write!(
561	        w,
562	        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
563	        tungstenite::handshake::derive_accept_key(key.as_bytes())
564	    )?;
565	    w.flush()
566	}
567	
568	fn reason(status: u16) -> &'static str {
569	    match status {
570	        200 => "OK",
571	        400 => "Bad Request",
572	        401 => "Unauthorized",
573	        403 => "Forbidden",
574	        404 => "Not Found",
575	        405 => "Method Not Allowed",
576	        413 => "Content Too Large",
577	        429 => "Too Many Requests",
578	        503 => "Service Unavailable",
579	        504 => "Gateway Timeout",
580	        _ => "Error",
581	    }
582	}
583	
584	/// Write one JSON response. Head and body in one write, so a reply is
585	/// one TLS record and one segment. Every reply says it is not to be
586	/// cached and not to be sniffed, which no native client reads and a
587	/// browser does; the reply's own headers follow.
588	fn respond<W: Write>(w: &mut W, reply: &RemoteReply) -> io::Result<()> {
589	    let mut out = format!(
590	        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n",
591	        reply.status,
592	        reason(reply.status),
593	        reply.body.len()
594	    );
595	    for (name, value) in &reply.headers {
596	        let _ = write!(out, "{name}: {value}\r\n");
597	    }
598	    out.push_str("\r\n");
599	    let mut out = out.into_bytes();
600	    out.extend_from_slice(&reply.body);
601	    w.write_all(&out)?;
602	    w.flush()
603	}
604	
605	/// Write one of the web page's files, with the policy headers that keep
606	/// the page to itself, and close: a page load is a burst of short
607	/// requests from a stranger, and a kept connection would hold one of
608	/// the unauthenticated pool's four slots for the idle timeout.
609	fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
610	    let mut out = format!(
611	        "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n",
612	        page.content_type,
613	        page.body.len()
614	    );
615	    for (name, value) in web::HEADERS {
616	        let _ = write!(out, "{name}: {value}\r\n");
617	    }
618	    out.push_str("\r\n");
619	    let mut out = out.into_bytes();
620	    out.extend_from_slice(page.body.as_bytes());
621	    w.write_all(&out)?;
622	    w.flush()
623	}
624	
625	/// The error reply the connection thread sends for what never reaches
626	/// the frame.
627	fn error_reply(status: u16, code: &str, message: &str) -> RemoteReply {
628	    let body = serde_json::json!({ "error": { "code": code, "message": message } })
629	        .to_string()
630	        .into_bytes();
631	    RemoteReply::new(status, body, false)
632	}
633	
634	// --- the listener
635	
636	/// At most 16 connections, 4 of them unauthenticated. The 4 are a pool
637	/// of their own: a flood of strangers fills its own slots and never a
638	/// paired device's.
639	pub const MAX_UNAUTHENTICATED: usize = 4;
640	pub const MAX_PAIRED: usize = 12;
641	/// The TLS handshake and the first request line within this.
642	const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(5);
643	/// A paired device polling on a kept connection may sit idle this long
644	/// between requests.
645	const IDLE_TIMEOUT: Duration = Duration::from_secs(30);
646	const WRITE_TIMEOUT: Duration = Duration::from_secs(10);
647	/// How long a connection waits for the frame's answer. The frame
648	/// answers on its next pass, so this only matters if it has stalled.
649	pub(crate) const ANSWER_TIMEOUT: Duration = Duration::from_secs(60);
650	/// The frame drains at most this many requests per pass from a channel
651	/// this deep; a full channel answers 503 without reaching the frame.
652	pub const DRAIN_PER_PASS: usize = 8;
653	const INBOX: usize = 64;
654	/// `/pair`, `/info` and the web page's files per minute per listener,
655	/// answered 429 past it. A page load is three requests.
656	const PAIR_PER_MINUTE: usize = 6;
657	const INFO_PER_MINUTE: usize = 60;
658	pub const PAGE_PER_MINUTE: usize = 120;
659	
660	const PAIR_PATH: &str = "/api/v1/pair";
661	const INFO_PATH: &str = "/api/v1/info";
662	
663	#[derive(Default)]
664	struct Pools {
665	    unauthenticated: AtomicUsize,
666	    paired: AtomicUsize,
667	}
668	
669	/// Allows `max` events per `per`, counted on a sliding window.
670	struct RateWindow {
671	    stamps: VecDeque<Instant>,
672	    max: usize,
673	    per: Duration,
674	}
675	
676	impl RateWindow {
677	    fn new(max: usize, per: Duration) -> Self {
678	        Self {
679	            stamps: VecDeque::new(),
680	            max,
