/// The 101 that switches a connection to WebSocket. The request was
/// already read by `read_request`, so `tungstenite::accept` cannot be
/// used; the stream is wrapped with `from_raw_socket` after this.
fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
    write!(
        w,
        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
        tungstenite::handshake::derive_accept_key(key.as_bytes())
    )?;
    w.flush()
}

fn reason(status: u16) -> &'static str {
    match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Content Too Large",
        429 => "Too Many Requests",
        503 => "Service Unavailable",
        504 => "Gateway Timeout",
        _ => "Error",
    }
}

/// Write one JSON response. Head and body in one write, so a reply is
/// one TLS record and one segment. Every reply says it is not to be
/// cached and not to be sniffed, which no native client reads and a
/// browser does; the reply's own headers follow.
fn respond<W: Write>(w: &mut W, reply: &RemoteReply) -> io::Result<()> {
    let mut out = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n",
        reply.status,
        reason(reply.status),
        reply.body.len()
    );
    for (name, value) in &reply.headers {
        let _ = write!(out, "{name}: {value}\r\n");
    }
    out.push_str("\r\n");
    let mut out = out.into_bytes();
    out.extend_from_slice(&reply.body);
    w.write_all(&out)?;
    w.flush()
}

/// Write one of the web page's files, with the policy headers that keep
/// the page to itself, and close: a page load is a burst of short
/// requests from a stranger, and a kept connection would hold one of
/// the unauthenticated pool's four slots for the idle timeout.
fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
    let mut out = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n",
        page.content_type,
        page.body.len()
    );
    for (name, value) in web::HEADERS {
        let _ = write!(out, "{name}: {value}\r\n");
    }
    out.push_str("\r\n");
    let mut out = out.into_bytes();
    out.extend_from_slice(page.body.as_bytes());
    w.write_all(&out)?;
    w.flush()
}

/// The error reply the connection thread sends for what never reaches
/// the frame.
fn error_reply(status: u16, code: &str, message: &str) -> RemoteReply {
    let body = serde_json::json!({ "error": { "code": code, "message": message } })
        .to_string()
        .into_bytes();
    RemoteReply::new(status, body, false)
}

// --- the listener

/// At most 16 connections, 4 of them unauthenticated. The 4 are a pool
/// of their own: a flood of strangers fills its own slots and never a
/// paired device's.
pub const MAX_UNAUTHENTICATED: usize = 4;
pub const MAX_PAIRED: usize = 12;
/// The TLS handshake and the first request line within this.
const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(5);
/// A paired device polling on a kept connection may sit idle this long
/// between requests.
const IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const WRITE_TIMEOUT: Duration = Duration::from_secs(10);
/// How long a connection waits for the frame's answer. The frame
/// answers on its next pass, so this only matters if it has stalled.
pub(crate) const ANSWER_TIMEOUT: Duration = Duration::from_secs(60);
/// The frame drains at most this many requests per pass from a channel
/// this deep; a full channel answers 503 without reaching the frame.
pub const DRAIN_PER_PASS: usize = 8;
const INBOX: usize = 64;
/// `/pair`, `/info` and the web page's files per minute per listener,
/// answered 429 past it. A page load is three requests.
const PAIR_PER_MINUTE: usize = 6;
const INFO_PER_MINUTE: usize = 60;
pub const PAGE_PER_MINUTE: usize = 120;

const PAIR_PATH: &str = "/api/v1/pair";
const INFO_PATH: &str = "/api/v1/info";

#[derive(Default)]
struct Pools {
    unauthenticated: AtomicUsize,
    paired: AtomicUsize,
}

/// Allows `max` events per `per`, counted on a sliding window.
struct RateWindow {
    stamps: VecDeque<Instant>,
    max: usize,
    per: Duration,
}

impl RateWindow {
    fn new(max: usize, per: Duration) -> Self {
        Self {
            stamps: VecDeque::new(),
            max,
            per,
        }
    }

    fn allow(&mut self, now: Instant) -> bool {
        while self.stamps.front().is_some_and(|&t| now - t >= self.per) {
            self.stamps.pop_front();
        }
        if self.stamps.len() >= self.max {
            return false;
        }
        self.stamps.push_back(now);
        true
    }
}

struct Limits {
    pair: Mutex<RateWindow>,
    info: Mutex<RateWindow>,
    page: Mutex<RateWindow>,
}

impl Limits {
    /// Whether a request for `path` is over its window; a poisoned lock
    /// counts as over, never as open.
    fn limited(&self, path: &str) -> bool {
        let window = match path {
            PAIR_PATH => &self.pair,
            INFO_PATH => &self.info,
            _ if web::page(path).is_some() => &self.page,
            _ => return false,
        };
        !window.lock().map_or(true, |mut w| w.allow(Instant::now()))
    }
}

