    #[test]
    fn the_run_probes_once_a_tick_and_ignores_the_missing_file() {
        let (mut core, run, ..) = started();
        let (feedback, _) = round_paths(std::path::Path::new(PLAN), 1);
        let effects = core.dispatch(AppAction::Tick, Clock::at(200));
        assert_eq!(
            effects,
