    }

    #[test]
    fn a_new_session_without_replaces_leaves_the_views_alone() {
        let (mut core, pid, ids) = with_records(&[agent()], |_| None);
        core.seed_views(Views {
            sets: vec![hand_set(SpaceId::DEFAULT, &[(ids[0], at(0))])],
