            id: id.into(),
            project: "Orchard".into(),
            state: "active".into(),
            updated_ms,
            decisions,
            ..TicketView::default()
        };
        let mut st = status(None);
        st.tickets = vec![
            ticket("t2", 50, vec![decision("t2", "d1", 20)]),
            ticket(
                "t1",
