    core.seed_status(
        Some(Notice {
            text: "saved".into(),
            is_error: false,
            expires_at: None,
            space: None,
            undo: None,
        }),
        None,
        false,
    );
    core.dispatch(AppAction::ShowSpace(SpaceId::DEFAULT), Clock::at(4));
    assert_eq!(shown(&core).as_deref(), Some("saved"));
