    #[test]
    fn a_tickets_agent_at_a_prompt_of_its_own_is_listed_with_its_attempt() {
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, agent(), 0);
        r.waiting_on = Some("lanes decision".into());
