    assert_eq!(listed[1]["attempt"], "investigate/1");
    assert_eq!(reply["body"]["last"], 2);
    assert_eq!(reply["body"]["unavailable"], false);
    // Again, from the cache.
    let (status, reply) = get(&mut port, events, t);
